'use server'

import { revalidatePath } from 'next/cache'

/**
 * In-memory store for the demo. In a real app this would be a database call
 * keyed by the authenticated user's id. Module-level state persists across
 * Server Action invocations within the same server process.
 */
let notificationsEnabled = false

export async function getNotificationPreference(): Promise<boolean> {
  return notificationsEnabled
}

export async function toggleNotifications(): Promise<void> {
  notificationsEnabled = !notificationsEnabled

  // Next.js recommended way to refresh the *current* page from within a
  // Server Action: revalidatePath clears the cached data for the given route
  // and re-renders it on the next request, WITHOUT a client-side redirect.
  // This keeps the user on the same URL while showing the updated preference.
  revalidatePath('/')
}

