import { getNotificationPreference, toggleNotifications } from './actions'

export default async function Home() {
  const notificationsEnabled = await getNotificationPreference()

  return (
    <main>
      <h1>Settings</h1>
      <p>
        Notifications are currently <strong>{notificationsEnabled ? 'on' : 'off'}</strong>.
      </p>
      <form action={toggleNotifications}>
        <button type="submit">
          Turn notifications {notificationsEnabled ? 'off' : 'on'}
        </button>
      </form>
    </main>
  )
}

